1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** What each item is insured for; distinct from what it costs to insure. */
61	const INSURANCE_VALUES: Record<string, number | undefined> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
72	
73	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
74	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
75	
76	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
77	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
78	
79	const basePremiumFor = (item: Item): number => {
80	  const basePremium = BASE_PREMIUMS[item.type];
81	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
82	  return basePremium;
83	};
84	
85	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
86	  values.reduce((total, value) => total + amountOf(value), 0);
87	
88	/** A building block of 3 alike components is offered at a special base premium. */
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	
92	const alikeComponentGroups = (items: Item[]): Item[][] => [
93	  ...items
94	    .reduce(
95	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
96	      new Map<string, Item[]>(),
97	    )
98	    .values(),
99	];
100	
101	const basePremiumForGroup = (group: Item[]): number =>
102	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
103	
104	const HIGH_ENCHANTMENT_THRESHOLD = 5;
105	
106	const isCursed = (item: Item): boolean => item.cursed === true;
107	
108	const isHighlyEnchanted = (item: Item): boolean =>
109	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
110	
111	/**
112	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
113	 * subjects it applies to. Modifiers that apply stack additively.
114	 */
115	interface Modifier<Subject> {
116	  appliesTo: (subject: Subject) => boolean;
117	  rate: number;
118	}
119	
120	const combinedRateOf = <Subject>(
121	  modifiers: Modifier<Subject>[],
122	  subject: Subject,
123	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
124	
125	/** Item-specific modifiers are levied on the affected item's own base premium. */
126	const ITEM_MODIFIERS: Modifier<Item>[] = [
127	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
128	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
129	];
130	
131	const itemSurchargeFor = (item: Item): number =>
132	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
133	
134	const LOYALTY_THRESHOLD_YEARS = 2;
135	
136	/**
137	 * The circumstances a single quote is issued under: who is being quoted, and
138	 * where this contract falls in their history with the MHPCO. Policy-wide
139	 * modifiers are decided from this alone.
140	 */
141	interface QuoteContext {
142	  customer: Customer;
143	  isFollowUpContract: boolean;
144	}
145	
146	const isLongStanding = ({ customer }: QuoteContext): boolean =>
147	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
148	
149	const followsAnEarlierContract = ({ isFollowUpContract }: QuoteContext): boolean =>
150	  isFollowUpContract;
151	
152	const appliesToEveryQuote = (): boolean => true;
153	
154	/** Policy-wide modifiers are levied on the whole policy's base premium. */
155	const POLICY_MODIFIERS: Modifier<QuoteContext>[] = [
156	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
157	  { appliesTo: appliesToEveryQuote, rate: INITIAL_ASSESSMENT_SURCHARGE },
158	  { appliesTo: followsAnEarlierContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
159	];
160	
161	/**
162	 * Item-specific modifiers are levied on the affected item's own base premium,
163	 * while policy-wide modifiers are levied on the policy base premium — the sum
164	 * of the item base premiums, before any item surcharge is added.
165	 */
166	const quote = (step: QuoteStep, context: QuoteContext): StepResult => {
167	  const policyBasePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
168	  const itemSurcharges = sumOf(step.items, itemSurchargeFor);
169	  const policyAdjustment = policyBasePremium * combinedRateOf(POLICY_MODIFIERS, context);
170	  return {
171	    premium: roundUpToWholeG(
172	      policyBasePremium + itemSurcharges + policyAdjustment + PROCESSING_FEE,
173	    ),
174	  };
175	};
176	
177	const insuranceValueFor = (item: Item): number => {
178	  const insuranceValue = INSURANCE_VALUES[item.type];
179	  if (insuranceValue === undefined) throw new Error(`Unknown item type: ${item.type}`);
180	  return insuranceValue;
181	};
182	
183	/** A policy created by a quote step, against which later claims are settled. */
184	interface Policy {
185	  items: Item[];
186	  remainingCap: number;
187	}
188	
189	const policyFor = (step: QuoteStep): Policy => ({
190	  items: step.items,
191	  remainingCap: sumOf(step.items, insuranceValueFor) * CAP_MULTIPLE_OF_INSURANCE_SUM,
192	});
193	
194	const payoutForDamage = (damage: Damage): number =>
195	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
196	
197	const claim = (step: ClaimStep, policy: Policy): StepResult => {
198	  const payout = sumOf(step.incident.damages, payoutForDamage);
199	  policy.remainingCap -= payout;
200	  return { payout, remainingCap: policy.remainingCap };
201	};
202	
203	/**
204	 * Steps are not independent: a quote's premium depends on whether an earlier
205	 * quote in the same scenario already established a contract, and a claim is
206	 * settled against the policy an earlier quote created.
207	 */
208	export const runScenario = (scenario: Scenario): ScenarioResult => {
209	  const policies = new Map<number, Policy>();
210	  let hasQuoted = false;
211	
212	  const results = scenario.steps.map((step, index) => {
213	    if (step.op === "quote") {
214	      const result = quote(step, {
215	        customer: scenario.customer,
216	        isFollowUpContract: hasQuoted,
217	      });
218	      policies.set(index, policyFor(step));
219	      hasQuoted = true;
220	      return result;
221	    }
222	
223	    const policy = policies.get(step.policy);
224	    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
225	    return claim(step, policy);
226	  });
227	
228	  return { results };
229	};
